import java.util.*;
import java.io.*;

public class Main {
    static final long MODULUS = 1000000007L;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int n_input = Integer.parseInt(br.readLine().trim());
        long[] probabilities = new long[n_input];
        List<Long>[] groups = new ArrayList[9];
        for (int i = 0; i <= 8; i++) {
            groups[i] = new ArrayList<>();
        }
        long[] popcount_counts = new long[1 << n_input];
        Map<Long, Long>[] dp_states = new HashMap[n_input + 1];
        for (int i = 0; i <= n_input; i++) {
            dp_states[i] = new HashMap<>();
        }
        long total_count = 0;

        // Precompute groups based on popcount
        for (long index_i = 0; index_i < (1L << n_input); index_i++) {
            int popcount = Long.bitCount(index_i);
            popcount_counts[(int)index_i] = groups[popcount].size();
            groups[popcount].add(index_i);
        }

        // Initialize DP
        dp_states[0].put(1L, 1L);

        for (int i = 0; i < n_input; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < n_input; j++) {
                long p = Long.parseLong(st.nextToken());
                probabilities[j] = p * 570000004L % MODULUS;
            }

            for (Map.Entry<Long, Long> stateEntry : dp_states[i].entrySet()) {
                long stateMask = stateEntry.getKey();
                long stateCount = stateEntry.getValue();

                long[] aux = new long[n_input];
                Arrays.fill(aux, 0L);

                for (long m : groups[(int) Long.bitCount(stateMask)]) {
                    int popCountM = Long.bitCount(m);
                    if (((stateMask >> popCountM) & 1) != 0) {
                        for (int j = 0; j < n_input; j++) {
                            if (((m >> j) & 1) == 0) {
                                int newPopCount = Long.bitCount(m | (1L << j));
                                aux[j] |= (1L << newPopCount);
                            }
                        }
                    }
                }

                int maxMask = 1 << n_input;
                for (int mask = 0; mask < maxMask; mask++) {
                    long product_val = 1L;
                    long sum_val = 0L;
                    for (int j = 0; j < n_input; j++) {
                        if (((mask >> j) & 1) != 0) {
                            sum_val |= aux[j];
                            product_val = (product_val * probabilities[j]) % MODULUS;
                        } else {
                            long val = (MODULUS - probabilities[j]) + 1;
                            product_val = (product_val * val) % MODULUS;
                        }
                    }
                    long prevCount = dp_states[i + 1].getOrDefault(sum_val, 0L);
                    long newCount = (prevCount + stateCount * product_val) % MODULUS;
                    dp_states[i + 1].put(sum_val, newCount);
                }
            }
        }

        System.out.println(dp_states[n_input].getOrDefault(1L, 0L));
    }
}
